/// <summary>
/// COC for table AgreementLine
/// Added for CB202 Sales quota by Akshay
/// </summary>
[ExtensionOf(tableStr(AgreementLine))]
final class METAgreementLine_Extension
{
}

Method.Source:
    /// <summary>
    /// Gets the remaining value/volume to be fulfilled by sales order line for given agreement line
    /// </summary>
    /// <returns>Value to be fulfilled</returns>
    public Amount metGetAgreementLineRemainingAmount()
    {
        Amount           remainingAmount;
        #AgreementsRemains

        container fulfillmentValues = AgreementLine::calculateFulfillmentForLine(this);

        remainingAmount = conPeek(fulfillmentValues, #RemainingIndex);

        return remainingAmount;
    }

    /// <summary>
    /// Gets the remaining qty to be fulfilled by sales order line for given agreement line
    /// </summary>
    /// <returns>Qty to be fulfilled</returns>
    public Qty metGetAgreementLineRemainingInventQty()
    {
        SalesQty                        salesQtyRemainAgreement;
        #AgreementsRemains
        container fulfillmentValues = AgreementLine::calculateFulfillmentForLine(this);

        salesQtyRemainAgreement = conPeek(fulfillmentValues, #RemainingIndex);

        return salesQtyRemainAgreement;
    }
